"""Author and validate 120 independent Linux practice tickets."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parent
LABS=[]
def F(data='',mode='644',owner='root',group='root',dir=False):
    return dict(data=data,mode=mode,owner=owner,group=group,dir=dir)
def G(label,*rule): return dict(label=label,rule=list(rule))
def add(topic,title,scenario,solution,goals,seed=None,edits=None,hint=None,patterns=None):
    LABS.append(dict(id=f'X{len(LABS)+1:03}',topic=topic,title=title,scenario=scenario,solution=solution,goals=goals,seed=seed or {},edits=edits or {},hint=hint or 'Inspect the evidence first. Each command changes only this ticket’s virtual server. Open the solution if you need supported syntax.',level='Lecture 2' if len(LABS)<84 else 'Lecture 3',scriptPatterns=patterns))

P='/srv/app/secret.env'; T='/srv/app/tasks.txt'; U='/etc/systemd/system/opsdemo.service'; N='/etc/nginx/app.conf'; S='/etc/ssh/sshd_config'; B='/etc/systemd/system/backup.timer'
TASKS='Inspect logs\nTest restore\n'
UNIT='[Service]\nUser=opsdemo\nExecStart=/usr/bin/python3 /opt/opsdemo/current/app.py\nRestart=on-failure\nNoNewPrivileges=yes\nPrivateTmp=yes\nProtectSystem=strict\nReadWritePaths=/var/lib/opsdemo\nMemoryMax=256M\n'
PROXY='server {\n listen 8080;\n location / {\n  proxy_pass http://127.0.0.1:8765;\n  proxy_set_header Host $host;\n  proxy_set_header X-Real-IP $remote_addr;\n }\n}\n'
SSH='PubkeyAuthentication yes\nPermitRootLogin no\nPasswordAuthentication no\nKbdInteractiveAuthentication no\n'

# 01 — Four different access policies, not just different file names.
add('File permissions','Make a token owner-only','A copied service token is readable and writable by everyone. Restrict access to its owner and inspect the result.',[f'chmod 600 {P}',f'ls -l {P}'],[G('Token mode is 600','mode',P,'600'),G('Inspect the protected token metadata','seen','ls:'+P)])
add('File permissions','Publish a read-only notice','A notice should be readable by all users but writable only by its owner. Remove its executable bit.', ['chmod 644 /srv/app/notice.txt','ls -l /srv/app/notice.txt'],[G('Notice uses 644','mode','/srv/app/notice.txt','644'),G('Inspect notice metadata','seen','ls:/srv/app/notice.txt')],{'fs':{'/srv/app/notice.txt':F('Maintenance at 18:00\n','777')}})
add('File permissions','Share a group configuration','Deployment staff need read access to a configuration. Others should have none.', ['chgrp deploy /srv/app/config.ini','chmod 640 /srv/app/config.ini','ls -l /srv/app/config.ini'],[G('Configuration belongs to deploy','group','/srv/app/config.ini','deploy'),G('Only owner can write; group can read','mode','/srv/app/config.ini','640'),G('Inspect configuration metadata','seen','ls:/srv/app/config.ini')])
add('File permissions','Make a private executable helper','A helper contains internal paths. Let its owner execute it while blocking all other access.', ['chmod 700 /lab/args.sh','ls -l /lab/args.sh'],[G('Helper mode is 700','mode','/lab/args.sh','700'),G('Inspect helper metadata','seen','ls:/lab/args.sh')])

# 02
add('Directory permissions','Protect a home workspace','The student workspace has inherited a public mode. Permit only the student to traverse it.', ['chown student:student /home/student','chmod 700 /home/student','ls -l /home/student'],[G('Workspace belongs to student','owner','/home/student','student'),G('Private directory mode is 700','mode','/home/student','700'),G('Inspect the directory','seen','ls:/home/student')])
add('Directory permissions','Create a group-inheriting release area','New release files should inherit the deploy group. Configure a shared directory with setgid.', ['chgrp deploy /srv/releases','chmod 2770 /srv/releases','ls -l /srv/releases'],[G('Release group is deploy','group','/srv/releases','deploy'),G('Setgid and group access are set','mode','/srv/releases','2770'),G('Inspect release directory','seen','ls:/srv/releases')])
add('Directory permissions','Protect a shared scratch directory','Everyone may create files in scratch, but the directory needs the sticky bit to constrain removal of other users’ entries.', ['mkdir /srv/scratch','chmod 1777 /srv/scratch','ls -l /srv/scratch'],[G('Scratch directory exists','dir','/srv/scratch'),G('Sticky directory mode is 1777','mode','/srv/scratch','1777'),G('Inspect scratch metadata','seen','ls:/srv/scratch')],hint='The mode sets policy here; this simulator does not emulate deletion authorization. On Linux the sticky bit restricts who may remove entries.')
add('Directory permissions','Give a team traversal without listing','A handoff directory should allow owner access and group traversal, but no group directory listing.', ['chgrp deploy /srv/handoff','chmod 710 /srv/handoff','ls -l /srv/handoff'],[G('Handoff group is deploy','group','/srv/handoff','deploy'),G('Group receives x without r','mode','/srv/handoff','710'),G('Inspect handoff metadata','seen','ls:/srv/handoff')],{'fs':{'/srv/handoff':F('','777',dir=True)}})

# 03
add('Ownership','Return data to the service account','A root-run repair left task data under root ownership. Restore the service identity without widening access.',[f'chown opsdemo:opsdemo {T}',f'chmod 640 {T}',f'ls -l {T}'],[G('Service owns task data','owner',T,'opsdemo'),G('Service group owns task data','group',T,'opsdemo'),G('Mode remains constrained','mode',T,'640'),G('Inspect task metadata','seen','ls:'+T)],{'fs':{T:F(TASKS,'600')}})
add('Ownership','Transfer a developer handoff file','Sara is taking responsibility for a handoff note. Transfer its ownership while retaining team read access.', ['chown sara:deploy /srv/app/handoff.txt','chmod 640 /srv/app/handoff.txt','ls -l /srv/app/handoff.txt'],[G('Sara owns the note','owner','/srv/app/handoff.txt','sara'),G('Deploy group can read','group','/srv/app/handoff.txt','deploy'),G('Note mode is 640','mode','/srv/app/handoff.txt','640'),G('Inspect note metadata','seen','ls:/srv/app/handoff.txt')],{'fs':{'/srv/app/handoff.txt':F('Handoff\n')}})
add('Ownership','Repair an SSH directory tree','Sara’s public key tree is owned by root. Correct the tree and secure both directory and key file.', ['chown -R sara:sara /home/sara/.ssh','chmod 700 /home/sara/.ssh','chmod 600 /home/sara/.ssh/authorized_keys','ls -l /home/sara/.ssh'],[G('Directory owner corrected','owner','/home/sara/.ssh','sara'),G('Key owner corrected','owner','/home/sara/.ssh/authorized_keys','sara'),G('Directory protected','mode','/home/sara/.ssh','700'),G('Public-key file protected','mode','/home/sara/.ssh/authorized_keys','600')])
add('Ownership','Separate executable code from writable data','The service should read deployed code but not own it. Give code to root and the data file to opsdemo.', ['chown root:root /srv/app/config.ini',f'chown opsdemo:opsdemo {T}','chmod 644 /srv/app/config.ini',f'ls -l {T}'],[G('Code configuration owned by root','owner','/srv/app/config.ini','root'),G('Data owned by service','owner',T,'opsdemo'),G('Code mode is 644','mode','/srv/app/config.ini','644'),G('Inspect separated data ownership','seen','ls:'+T)],{'fs':{'/srv/app/config.ini':F('port=8765\n','666','opsdemo','opsdemo'),T:F(TASKS,'640')}})

# 04
add('User accounts','Onboard an auditor with a home','Create a distinct audit account rather than sharing the administrator’s account.', ['getent passwd','useradd -m auditor','id auditor'],[G('Inspect existing accounts','seen','accounts'),G('Auditor exists','user','auditor'),G('Auditor has a home','home','auditor'),G('Inspect new account','seen','id:auditor')])
add('User accounts','Create a noninteractive worker identity','A batch worker needs an identity and no home directory. This ticket models identity creation only; a real service account also needs an appropriate login shell policy.', ['useradd batch','id batch'],[G('Batch identity exists','user','batch'),G('Inspect worker identity','seen','id:batch')],hint='useradd without -m does not create a home in this training model. It does not by itself disable interactive login on a real machine.')
add('User accounts','Create a group before the account handoff','Prepare a reporting group, create Rami’s individual account, and grant the reporting membership.', ['groupadd reporting','useradd -m rami','usermod -aG reporting rami','id rami'],[G('Reporting group exists','groupExists','reporting'),G('Rami has a home','home','rami'),G('Rami joins reporting','member','rami','reporting'),G('Inspect Rami identity','seen','id:rami')])
add('User accounts','Give two operators individual identities','Two operators need separate homes and membership in the same existing deployment team.', ['useradd -m lina','useradd -m omar','usermod -aG deploy lina','usermod -aG deploy omar','getent group'],[G('Lina has a home','home','lina'),G('Omar has a home','home','omar'),G('Lina joins deploy','member','lina','deploy'),G('Omar joins deploy','member','omar','deploy'),G('Inspect group database','seen','groups')])

# 05
add('Group memberships','Add monitoring without removing deployment','Sara already belongs to deploy. Add monitoring while preserving her existing team access.', ['groupadd monitoring','usermod -aG monitoring sara','id sara'],[G('Preserve deploy membership','member','sara','deploy'),G('Add monitoring membership','member','sara','monitoring'),G('Inspect final memberships','seen','id:sara')],{'users':{'sara':{'home':'/home/sara','groups':['sara','deploy']}}})
add('Group memberships','Remove obsolete deployment access','An operator has moved to reporting. Remove only the deploy membership.', ['gpasswd -d sara deploy','id sara'],[G('Deploy membership removed','notMember','sara','deploy'),G('Primary group retained','member','sara','sara'),G('Inspect resulting identity','seen','id:sara')],{'users':{'sara':{'home':'/home/sara','groups':['sara','deploy']}}})
add('Group memberships','Create an incident-response team','Create a responders group and add Sara and the student without replacing their existing groups.', ['groupadd responders','usermod -aG responders sara','usermod -aG responders student','getent group'],[G('Response group exists','groupExists','responders'),G('Sara is a responder','member','sara','responders'),G('Student is a responder','member','student','responders'),G('Inspect team database','seen','groups')])
add('Group memberships','Keep service and human identities separate','The service needs read membership in a logs group. Add it without giving the student that membership.', ['groupadd logs','usermod -aG logs opsdemo','id opsdemo','id student'],[G('Service joins logs','member','opsdemo','logs'),G('Student is not added to logs','notMember','student','logs'),G('Inspect service identity','seen','id:opsdemo'),G('Inspect human identity','seen','id:student')])

# 06
for title,scenario,mask,mode,dmode in [
 ('Default to private artifacts','A secret-generation session must create owner-only files and private directories.','077','600','700'),
 ('Default to team-readable artifacts','A reporting session needs files readable by its group but no access for others.','027','640','750'),
 ('Default to public-readable artifacts','A documentation build should create readable files without making them executable.','022','644','755'),
 ('Default to collaborative artifacts','A shared development session needs group-writable files and directories.','002','664','775')]:
 add('Umask and creation',title,scenario,[f'umask {mask}','mkdir /srv/generated','touch /srv/generated/result.txt','ls -l /srv/generated'],[G('New directory receives expected mode','mode','/srv/generated',dmode),G('New ordinary file receives expected mode','mode','/srv/generated/result.txt',mode),G('Inspect created entries','seen','ls:/srv/generated')],hint='Umask removes requested permission bits. Ordinary files begin at 666, directories at 777; it does not grant execute permission to ordinary files.')

