add('Named-user ACLs','Let an auditor read one configuration','Grant Sara read-only ACL access without changing the file’s owning group.', ['setfacl -m u:sara:r-- /srv/app/config.ini','getfacl /srv/app/config.ini'],[G('Sara has named read permission','acl','/srv/app/config.ini','sara','r--'),G('Inspect stored ACL','seen','acl:/srv/app/config.ini')])
add('Named-user ACLs','Grant directory traversal to a collaborator','Sara needs to list and traverse release files without writing into the release directory.', ['setfacl -m u:sara:r-x /srv/releases','getfacl /srv/releases'],[G('Sara receives r-x on the directory','acl','/srv/releases','sara','r-x'),G('Inspect release ACL','seen','acl:/srv/releases')])
add('Named-user ACLs','Grant service read access to a report','Keep root ownership while adding a named ACL for the service identity.', ['setfacl -m u:opsdemo:r-- /srv/app/report.txt','getfacl /srv/app/report.txt','ls -l /srv/app/report.txt'],[G('Service gets named read access','acl','/srv/app/report.txt','opsdemo','r--'),G('Root remains owner','owner','/srv/app/report.txt','root'),G('Inspect report ACL','seen','acl:/srv/app/report.txt')],{'fs':{'/srv/app/report.txt':F('Daily report\n','600')}})
add('Named-user ACLs','Revoke a temporary named ACL grant','A temporary maintenance window has ended. Set Sara’s named entry to no access and inspect it.', ['setfacl -m u:sara:--- /srv/app/config.ini','getfacl /srv/app/config.ini'],[G('Named grant has no permissions','acl','/srv/app/config.ini','sara','---'),G('Inspect revoked grant','seen','acl:/srv/app/config.ini')],{'acls':{'/srv/app/config.ini':{'sara':'rw-'}}},hint='The simulator models named user entries with an automatically widened mask. Real getfacl also shows effective rights and ACL masks. A named --- entry is different from deleting the entry.')

