add('Process signals','Gracefully stop a background report','Identify the report process before sending a catchable termination request.', ['pgrep report','kill -TERM 5000','ps -ef'],[G('Locate report PID','seen','pgrep:report'),G('Report has exited','procGone','5000'),G('SIGTERM used','signal','5000','TERM'),G('Inspect remaining processes','seen','processes')])
add('Process signals','Escalate an unresponsive worker','The ticket records that a previous graceful request timed out. Identify the worker and use the forced signal authorized for this simulation.', ['pgrep worker','kill -KILL 4242','ps -ef'],[G('Locate worker','seen','pgrep:worker'),G('Worker removed','procGone','4242'),G('Forced signal used','signal','4242','KILL'),G('Inspect survivors','seen','processes')],hint='SIGKILL cannot be caught and prevents process cleanup. This scenario explicitly assumes a prior failed graceful stop.')
add('Process signals','Stop one worker without killing another','Two separate jobs are running. Stop the report while preserving the worker for unrelated requests.', ['ps -ef','kill -TERM 5000','pgrep worker'],[G('Report stopped','procGone','5000'),G('Worker still running','procExists','4242'),G('Inspect worker survivor','seen','pgrep:worker'),G('Inspect process list','seen','processes')])
add('Process signals','Drain two retired jobs','Both training background jobs belong to a retired batch. Inspect and gracefully terminate each PID.', ['ps -ef','kill -TERM 4242','kill -TERM 5000'],[G('Inspect initial processes','seen','processes'),G('Worker stopped','procGone','4242'),G('Report stopped','procGone','5000')])

# 09
for title,scenario,pid,nice in [
 ('Deprioritize a CPU-heavy report','A nonurgent report competes with interactive work. Lower its scheduling priority without killing it.','5000',10),
 ('Keep a background worker polite','A maintenance worker may continue but should have the lowest normal nice priority.','4242',19),
 ('Use a moderate batch priority','A reporting job needs a modest priority reduction rather than the maximum adjustment.','5000',5),
 ('Return a simulated worker to normal priority','A worker inherited nice 15. In this authorized simulation restore its normal priority.','4242',0)]:
 add('Scheduling priority',title,scenario,['ps -ef',f'renice -n {nice} -p {pid}','ps -ef'],[G('Inspect process evidence','seen','processes'),G('Selected process has the intended nice value','nice',pid,nice)],{'processes':{pid:{'name':'worker' if pid=='4242' else 'report','nice':15 if nice==0 else 0}}},hint='A larger nice value means lower scheduling priority; nice is not a CPU quota. Lowering the numerical nice value can require additional privilege on real Linux.')

