add('Service lifecycle','Stop an application for maintenance','Perform a planned stop while preserving its enabled boot policy for the next startup.', ['systemctl stop opsdemo','systemctl status opsdemo'],[G('Application inactive','service','opsdemo','active',False),G('Boot policy preserved','service','opsdemo','enabled',True),G('Inspect stopped state','seen','status:opsdemo')],{'services':{'opsdemo':{'active':True,'enabled':True}}})

