for title,scenario,key in [
 ('Disable direct root SSH login','Individual keys already work. Remove direct root login and inspect the effective policy.','PermitRootLogin'),
 ('Remove SSH password authentication','A second key session is available. Disable password authentication without changing the working key method.','PasswordAuthentication'),
 ('Remove keyboard-interactive login','The key path is verified. Disable keyboard-interactive authentication for this single-file training policy.','KbdInteractiveAuthentication'),
 ('Complete a key-only SSH policy','Replace all permissive root and password settings after verifying the independent key connection.','all')]:
 text=SSH if key=='all' else 'PubkeyAuthentication yes\nPermitRootLogin '+('no' if key=='PermitRootLogin' else 'yes')+'\nPasswordAuthentication '+('no' if key=='PasswordAuthentication' else 'yes')+'\nKbdInteractiveAuthentication '+('no' if key=='KbdInteractiveAuthentication' else 'yes')+'\n'
 goals=[G('Test independent public-key connection','seen','keyLogin'),G('Validate saved policy','seen','sshValidated'),G('Inspect effective policy','seen','effectiveSSH')]+([G('All insecure authentication paths disabled','all',*[[ 'ssh',k,'no'] for k in ['PermitRootLogin','PasswordAuthentication','KbdInteractiveAuthentication']])] if key=='all' else [G('Selected SSH setting is disabled','ssh',key,'no')])
 add('SSH hardening',title,scenario,['ssh -o PreferredAuthentications=publickey sara@server.test','edit '+S,'sshd -t','systemctl reload ssh','sshd -T'],goals,edits={S:text},hint='Keep recovery access and an existing session on real hosts. The lab models one SSH config file on port 22, without drop-ins, PAM or Match blocks.')

